/// .. _application-notification:
///
/// Application Notification
/// ------------------------
///
/// The ApplicationNotification enum indicates the type of notification for the
/// server/client in which the corresponding callback is configured.
///
/// The notification comes with a key-value map for the payload. Future
/// additional payload members are added to the end of the payload. So that the
/// names, type and also index of the payload members is stable.
enum UA_ApplicationNotificationType {
  UA_APPLICATIONNOTIFICATIONTYPE_LIFECYCLE_STARTED(0),
  UA_APPLICATIONNOTIFICATIONTYPE_LIFECYCLE_SHUTDOWN(1),
  UA_APPLICATIONNOTIFICATIONTYPE_LIFECYCLE_STOPPING(2),
  UA_APPLICATIONNOTIFICATIONTYPE_LIFECYCLE_STOPPED(3),
  UA_APPLICATIONNOTIFICATIONTYPE_SECURECHANNEL_OPENED(4),
  UA_APPLICATIONNOTIFICATIONTYPE_SECURECHANNEL_CLOSED(5),
  UA_APPLICATIONNOTIFICATIONTYPE_SESSION_CREATED(6),
  UA_APPLICATIONNOTIFICATIONTYPE_SESSION_ACTIVATED(7),
  UA_APPLICATIONNOTIFICATIONTYPE_SESSION_DEACTIVATED(8),
  UA_APPLICATIONNOTIFICATIONTYPE_SESSION_CLOSED(9),
  UA_APPLICATIONNOTIFICATIONTYPE_SERVICE_BEGIN(10),
  UA_APPLICATIONNOTIFICATIONTYPE_SERVICE_ASYNC(11),
  UA_APPLICATIONNOTIFICATIONTYPE_SERVICE_END(12),
  UA_APPLICATIONNOTIFICATIONTYPE_SUBSCRIPTION_CREATED(13),
  UA_APPLICATIONNOTIFICATIONTYPE_SUBSCRIPTION_MODIFIED(14),
  UA_APPLICATIONNOTIFICATIONTYPE_SUBSCRIPTION_PUBLISHINGMODE(15),
  UA_APPLICATIONNOTIFICATIONTYPE_SUBSCRIPTION_TRANSFERRED(16),
  UA_APPLICATIONNOTIFICATIONTYPE_SUBSCRIPTION_DELETED(17),
  UA_APPLICATIONNOTIFICATIONTYPE_MONITOREDITEM_CREATED(18),
  UA_APPLICATIONNOTIFICATIONTYPE_MONITOREDITEM_MODIFIED(19),
  UA_APPLICATIONNOTIFICATIONTYPE_MONITOREDITEM_MONITORINGMODE(20),
  UA_APPLICATIONNOTIFICATIONTYPE_MONITOREDITEM_DELETE(21);

  final int value;
  const UA_ApplicationNotificationType(this.value);

  static UA_ApplicationNotificationType fromValue(int value) => switch (value) {
    0 => UA_APPLICATIONNOTIFICATIONTYPE_LIFECYCLE_STARTED,
    1 => UA_APPLICATIONNOTIFICATIONTYPE_LIFECYCLE_SHUTDOWN,
    2 => UA_APPLICATIONNOTIFICATIONTYPE_LIFECYCLE_STOPPING,
    3 => UA_APPLICATIONNOTIFICATIONTYPE_LIFECYCLE_STOPPED,
    4 => UA_APPLICATIONNOTIFICATIONTYPE_SECURECHANNEL_OPENED,
    5 => UA_APPLICATIONNOTIFICATIONTYPE_SECURECHANNEL_CLOSED,
    6 => UA_APPLICATIONNOTIFICATIONTYPE_SESSION_CREATED,
    7 => UA_APPLICATIONNOTIFICATIONTYPE_SESSION_ACTIVATED,
    8 => UA_APPLICATIONNOTIFICATIONTYPE_SESSION_DEACTIVATED,
    9 => UA_APPLICATIONNOTIFICATIONTYPE_SESSION_CLOSED,
    10 => UA_APPLICATIONNOTIFICATIONTYPE_SERVICE_BEGIN,
    11 => UA_APPLICATIONNOTIFICATIONTYPE_SERVICE_ASYNC,
    12 => UA_APPLICATIONNOTIFICATIONTYPE_SERVICE_END,
    13 => UA_APPLICATIONNOTIFICATIONTYPE_SUBSCRIPTION_CREATED,
    14 => UA_APPLICATIONNOTIFICATIONTYPE_SUBSCRIPTION_MODIFIED,
    15 => UA_APPLICATIONNOTIFICATIONTYPE_SUBSCRIPTION_PUBLISHINGMODE,
    16 => UA_APPLICATIONNOTIFICATIONTYPE_SUBSCRIPTION_TRANSFERRED,
    17 => UA_APPLICATIONNOTIFICATIONTYPE_SUBSCRIPTION_DELETED,
    18 => UA_APPLICATIONNOTIFICATIONTYPE_MONITOREDITEM_CREATED,
    19 => UA_APPLICATIONNOTIFICATIONTYPE_MONITOREDITEM_MODIFIED,
    20 => UA_APPLICATIONNOTIFICATIONTYPE_MONITOREDITEM_MONITORINGMODE,
    21 => UA_APPLICATIONNOTIFICATIONTYPE_MONITOREDITEM_DELETE,
    _ => throw ArgumentError('Unknown value for UA_ApplicationNotificationType: $value'),
  };
}

