/// Guid
/// ^^^^
/// A 16 byte value that can be used as a globally unique identifier.
final class UA_Guid extends ffi.Struct {
  @UA_UInt32()
  external int data1;

  @UA_UInt16()
  external int data2;

  @UA_UInt16()
  external int data3;

  @ffi.Array.multi([8])
  external ffi.Array<UA_Byte> data4;
}

