/// Global PubSub Configuration
/// ---------------------------
/// The following PubSub configuration structure is part of the server-config.
/// It configures behavior that is valid for all PubSubComponents.
final class UA_PubSubConfiguration extends ffi.Struct {
  external ffi.Pointer<
    ffi.NativeFunction<
      UA_StatusCode Function(
        ffi.Pointer<UA_Server> server,
        UA_NodeId id,
        ffi.UnsignedInt componentType,
        ffi.Bool remove,
      )
    >
  >
  componentLifecycleCallback;

  external ffi.Pointer<
    ffi.NativeFunction<
      ffi.Void Function(ffi.Pointer<UA_Server> server, UA_NodeId id, ffi.Pointer<ffi.UnsignedInt> targetState)
    >
  >
  beforeStateChangeCallback;

  external ffi.Pointer<
    ffi.NativeFunction<
      ffi.Void Function(ffi.Pointer<UA_Server> server, UA_NodeId id, ffi.UnsignedInt state, UA_StatusCode status)
    >
  >
  stateChangeCallback;

  @ffi.Bool()
  external bool enableDeltaFrames;

  @ffi.Bool()
  external bool enableInformationModelMethods;

  @ffi.Size()
  external int securityPoliciesSize;

  external ffi.Pointer<UA_PubSubSecurityPolicy> securityPolicies;

  static ffi.Pointer<UA_PubSubConfiguration> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<
      ffi.NativeFunction<
        UA_StatusCode Function(
          ffi.Pointer<UA_Server> server,
          UA_NodeId id,
          ffi.UnsignedInt componentType,
          ffi.Bool remove,
        )
      >
    >
    componentLifecycleCallback,
    required ffi.Pointer<
      ffi.NativeFunction<
        ffi.Void Function(ffi.Pointer<UA_Server> server, UA_NodeId id, ffi.Pointer<ffi.UnsignedInt> targetState)
      >
    >
    beforeStateChangeCallback,
    required ffi.Pointer<
      ffi.NativeFunction<
        ffi.Void Function(ffi.Pointer<UA_Server> server, UA_NodeId id, ffi.UnsignedInt state, UA_StatusCode status)
      >
    >
    stateChangeCallback,
    required bool enableDeltaFrames,
    required bool enableInformationModelMethods,
    required int securityPoliciesSize,
    required ffi.Pointer<UA_PubSubSecurityPolicy> securityPolicies,
  }) => $allocator<UA_PubSubConfiguration>()
    ..ref.componentLifecycleCallback = componentLifecycleCallback
    ..ref.beforeStateChangeCallback = beforeStateChangeCallback
    ..ref.stateChangeCallback = stateChangeCallback
    ..ref.enableDeltaFrames = enableDeltaFrames
    ..ref.enableInformationModelMethods = enableInformationModelMethods
    ..ref.securityPoliciesSize = securityPoliciesSize
    ..ref.securityPolicies = securityPolicies;
}

/// PubSubConnection
/// ----------------
/// PubSubConnections are the abstraction between the concrete transport protocol
/// and the PubSub functionality. It is possible to create multiple
/// PubSubConnections with (possibly) different transport protocols at
/// runtime.
final class UA_PubSubConnectionConfig extends ffi.Struct {
  external UA_String name;

  external ffi.Pointer<ffi.Void> context;

  @ffi.Bool()
  external bool enabled;

  external ffi.Pointer<
    ffi.NativeFunction<
      UA_StatusCode Function(
        ffi.Pointer<UA_Server> server,
        UA_NodeId componentId,
