/// ^^^^^^
/// An integer value between 0 and 65 535.
typedef UA_UInt16 = ffi.Uint16;
typedef DartUA_UInt16 = int;

/// UInt32
/// ^^^^^^
/// An integer value between 0 and 4 294 967 295.
typedef UA_UInt32 = ffi.Uint32;
typedef DartUA_UInt32 = int;

/// Range Definition
/// ----------------
final class UA_UInt32Range extends ffi.Struct {
  @UA_UInt32()
  external int min;

  @UA_UInt32()
  external int max;

  static ffi.Pointer<UA_UInt32Range> $allocate(ffi.Allocator $allocator, {required int min, required int max}) =>
      $allocator<UA_UInt32Range>()
        ..ref.min = min
        ..ref.max = max;
}

